"""Brute-force solvers written from the problem definitions."""

from __future__ import annotations

import itertools


def solve_three_sat(instance):
    m = instance["num_vars"]
    clauses = instance["clauses"]
    for bits in itertools.product([False, True], repeat=m):
        ok = True
        for clause in clauses:
            if not any((lit > 0) == bits[abs(lit) - 1] for lit in clause):
                ok = False
                break
        if ok:
            return True
    return False


def solve_vertex_cover(instance):
    """Exact vertex cover via recursive branching (still brute force)."""
    n = instance["n"]
    edges = [tuple(e) for e in instance["edges"]]
    k = instance["k"]
    if k < 0:
        return False
    if k >= n:
        return True
    if not edges:
        return True

    def rec(rem, budget):
        if not rem:
            return True
        if budget <= 0:
            return False
        # Greedy maximal matching lower bound.
        used = set()
        matching = 0
        for u, v in rem:
            if u not in used and v not in used:
                used.add(u)
                used.add(v)
                matching += 1
                if matching > budget:
                    return False
        # Branch on the vertex of maximum degree.
        deg = {}
        for u, v in rem:
            deg[u] = deg.get(u, 0) + 1
            deg[v] = deg.get(v, 0) + 1
        best = max(deg, key=lambda x: deg[x])
        new_rem = [e for e in rem if e[0] != best and e[1] != best]
        if rec(new_rem, budget - 1):
            return True
        # Otherwise must pick the other endpoint of an edge incident to best.
        for u, v in rem:
            if u == best:
                other = v
                break
            if v == best:
                other = u
                break
        else:
            return False
        new_rem2 = [e for e in rem if e[0] != other and e[1] != other]
        return rec(new_rem2, budget - 1)

    return rec(edges, k)
